const PAGE_HTML = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#f5f0df\"><meta name=\"description\" content=\"A public learning and discussion space for questions about intelligent futures.\"><title>Superintelligence SG · Commons — A public conversation</title><link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' rx='11' fill='%23ed593e'/%3E%3Cpath d='M9 23c7-15 10 8 17-8s7 1 7 1' fill='none' stroke='%23f5f0df' stroke-width='4' stroke-linecap='round'/%3E%3C/svg%3E\"><style>:root{--bg:#f5f0df;--ink:#1c2937;--muted:#606a70;--line:#b9b6a7;--accent:#ed593e;--buttonText:#fffaf0;--artBg:#d9e1b7;--grid:rgba(28,41,55,.08);--ring:rgba(47,92,122,.48);--band:#1c2937;--bandText:#f5f0df;--bandMuted:#c5ced0;--display:Georgia,serif;--serif:Georgia,'Iowan Old Style',serif;--sans:'Avenir Next',Avenir,'Segoe UI',sans-serif;--mono:'SFMono-Regular',Consolas,monospace}<style>\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--sans)}a{color:inherit;text-decoration:none}.wrap{width:min(1240px,90vw);margin:auto}.top{height:74px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:10px;font-size:13px;font-weight:850;letter-spacing:.02em}.brand i{font-style:normal;width:29px;height:29px;border-radius:9px;background:var(--accent);color:var(--bg);display:grid;place-items:center;font-size:19px}.nav{display:flex;gap:26px;align-items:center;font-size:12px;font-weight:700}.nav a:hover{color:var(--accent)}.nav .button{padding:9px 13px;border:1px solid var(--line)}.eyebrow{font:700 12px var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--accent)}h1,h2,h3,p{margin-top:0}h1{font:400 clamp(58px,8.4vw,112px)/.9 var(--display);letter-spacing:-.075em;margin:23px 0;max-width:760px}h1 em{color:var(--accent);font-weight:400}h2{font:400 clamp(40px,6vw,72px)/.96 var(--display);letter-spacing:-.06em}h3{font:400 26px/1.06 var(--display);letter-spacing:-.04em}.lead{max-width:570px;font:19px/1.55 var(--serif);color:var(--muted)}.cta{display:inline-flex;gap:18px;align-items:center;padding:13px 17px;background:var(--accent);color:var(--buttonText);font-size:12px;font-weight:800;margin-top:22px}.cta:hover{filter:brightness(1.08)}.hero{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:5vw;padding:85px 0 90px;min-height:610px}.art{min-height:390px;position:relative;overflow:hidden;background:var(--artBg);border:1px solid var(--line);display:grid;place-items:center}.art:before{content:\"\";position:absolute;inset:0;background:linear-gradient(var(--grid) 1px,transparent 1px),linear-gradient(90deg,var(--grid) 1px,transparent 1px);background-size:38px 38px}.rings{position:absolute;width:75%;aspect-ratio:1;border:1px solid var(--ring);border-radius:50%}.rings:before,.rings:after{content:\"\";position:absolute;inset:12%;border:1px dashed var(--ring);border-radius:50%;transform:scaleX(.6) rotate(37deg)}.rings:after{inset:28%;transform:scaleX(.72) rotate(-45deg);border-style:solid}.core{position:relative;width:105px;height:105px;border-radius:50%;background:var(--accent);display:grid;place-items:center;color:var(--buttonText);font:italic 24px var(--serif);z-index:1}.tag{position:absolute;z-index:2;padding:9px 11px;background:var(--bg);border:1px solid var(--line);font:11px var(--mono)}.tag.a{top:16%;left:8%}.tag.b{right:7%;top:27%}.tag.c{bottom:15%;left:13%}.section{padding:88px 0;border-top:1px solid var(--line)}.sectionhead{display:flex;justify-content:space-between;align-items:end;gap:4vw;margin-bottom:34px}.sectionhead p{max-width:340px;color:var(--muted);margin:0}.grid3{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.item{padding:24px 24px 30px 0;min-height:225px}.item+.item{border-left:1px solid var(--line);padding-left:24px}.item .num{font:italic 13px var(--serif);color:var(--accent)}.item h3{margin:30px 0 10px}.item p{color:var(--muted);font-size:15px;max-width:310px}.item a{font-size:12px;font-weight:700;color:var(--accent)}.band{padding:70px 0;background:var(--band);color:var(--bandText)}.bandrow{display:grid;grid-template-columns:.7fr 1.3fr;gap:6vw;align-items:center}.band h2{font-size:clamp(36px,5vw,60px);margin:0}.band p{font:19px/1.55 var(--serif);margin:0;color:var(--bandMuted)}.cross{padding:30px 0;display:flex;justify-content:space-between;gap:18px;align-items:center;color:var(--muted);font-size:12px}.crosslinks{display:flex;gap:10px;flex-wrap:wrap}.crosslinks a{border:1px solid var(--line);padding:9px 12px}.crosslinks a:hover{color:var(--accent);border-color:var(--accent)}footer{border-top:1px solid var(--line);padding:18px 0;display:flex;justify-content:space-between;gap:20px;font-size:12px;color:var(--muted)}\n@media(max-width:760px){.hero{grid-template-columns:1fr;padding:60px 0;gap:35px}.sectionhead{display:block}.sectionhead p{margin-top:16px}.grid3{grid-template-columns:1fr}.item,.item+.item{padding:22px 0;min-height:0;border-left:0}.item+.item{border-top:1px solid var(--line)}.item h3{margin:15px 0 8px}.bandrow{grid-template-columns:1fr;gap:20px}}\n@media(max-width:520px){.wrap{width:88vw}.top{height:66px}.nav{gap:12px}.nav a:not(.button){display:none}.hero{padding:50px 0;min-height:0}h1{font-size:clamp(56px,15vw,78px)}.art{min-height:320px}.rings{width:72%}.core{width:78px;height:78px;font-size:20px}.tag{font-size:10px}.section{padding:64px 0}.cross{display:block}.crosslinks{margin-top:15px}footer{flex-wrap:wrap}}\n@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\n</style><style>.orghero h1{max-width:790px}.sidequote{border-block:1px solid var(--ink);padding:22px 0}.sidequote b{display:block;font:italic 31px/1.1 var(--serif);font-weight:400;margin-bottom:10px}.sidequote p{font-size:14px;color:var(--muted);margin:0}.qnum{font:italic 13px var(--serif);color:var(--accent)}.guide{border-top:1px solid var(--line)}.guide-item{display:grid;grid-template-columns:80px 1fr 34px;gap:15px;padding:18px 0;border-bottom:1px solid var(--line);align-items:start}.guide-item h3{font-size:21px;margin:0 0 6px}.guide-item p{color:var(--muted);font-size:14px;margin:0}.guide-item .answer{display:none;padding-top:12px;color:#394951;font-size:14px;max-width:690px}.guide-item.open .answer{display:block}.guide-item button{border:1px solid var(--ink);background:transparent;border-radius:50%;width:30px;height:30px;cursor:pointer;font-size:17px}.guide-item button:hover,.guide-item.open button{background:var(--accent);color:white}.callout{padding:30px;background:#d9e1b7;border-left:3px solid var(--accent)}.callout h3{font-size:28px}.callout p{color:#4a5650;margin-bottom:0}@media(max-width:520px){.guide-item{grid-template-columns:55px 1fr 30px;gap:9px}}</style></style><style id=\"type-refinements\">\n:root{font-synthesis:none;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}\nbody{font-size:17px;line-height:1.72;letter-spacing:.005em}\n.brand{font-size:14px;letter-spacing:.035em}\n.nav{gap:28px;font-size:13px;line-height:1.4}\n.eyebrow{font-size:11px;letter-spacing:.11em;line-height:1.6}\nh1{font-size:clamp(58px,8vw,104px);line-height:1.02;letter-spacing:-.055em;text-wrap:balance;max-width:13ch}\nh2{line-height:1.08;letter-spacing:-.045em;text-wrap:balance}\nh3{line-height:1.18;letter-spacing:-.025em;text-wrap:balance}\np{max-width:65ch}\n.lead{max-width:52ch;font-size:20px;line-height:1.62;letter-spacing:0}\n.sectionhead p{max-width:42ch;font-size:17px;line-height:1.68}\n.item p{max-width:38ch;font-size:16px;line-height:1.65}\n.item h3{line-height:1.2}\n.cta{font-size:14px;line-height:1.4}\n.tag{font-size:12px;line-height:1.45}\n.band p{max-width:54ch;font-size:20px;line-height:1.65}\n.cross,footer{font-size:13px;line-height:1.6}\n.aihero h1{letter-spacing:-.055em;max-width:12ch}\n.controls h3{font-size:14px;letter-spacing:.01em}\n.controls p,.output p,.guide-item p,.guide-item .answer{font-size:16px;line-height:1.68}\n.options button{font-size:15px;line-height:1.45}\n.question{font-size:13px;line-height:1.55}\n.note{font-size:11px;line-height:1.6}\n.guide-item h3{font-size:22px;line-height:1.25}\n@media(max-width:760px){body{font-size:16.5px}.lead{font-size:19px}.sectionhead p{font-size:16px}.item p{font-size:16px}.guide-item p,.guide-item .answer,.controls p,.output p{font-size:15px}}\n@media(max-width:520px){.nav{gap:10px}.nav .button{font-size:12px;padding:8px 10px}h1{font-size:clamp(54px,14vw,76px);line-height:1.03;letter-spacing:-.05em}.lead{font-size:18px;line-height:1.65}.eyebrow{font-size:10.5px}.tag{font-size:11px}.sectionhead p{font-size:15.5px}.cross,footer{font-size:12.5px}}\n</style><style id=\"org-directory-styles\">\n.join-section{background:#e6e3cf}.join-heading{max-width:710px}.join-heading p{font-size:18px;line-height:1.65;color:var(--muted)}.join-shell{display:grid;grid-template-columns:.88fr 1.12fr;border:1px solid var(--ink);background:#f9f7ed;box-shadow:12px 12px 0 var(--ink)}.join-form{padding:clamp(22px,4vw,42px);border-right:1px solid var(--line)}.join-form-top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:24px}.open-label{display:inline-flex;align-items:center;gap:8px;font:700 12px var(--mono);letter-spacing:.08em;text-transform:uppercase}.open-label:before{content:\"\";width:9px;height:9px;border-radius:50%;background:#658d47}.join-form label{display:grid;gap:8px;margin:17px 0;font-size:14px;font-weight:700}.join-form input:not([type=checkbox]),.join-form textarea{width:100%;border:1px solid #8e9588;border-radius:0;background:#fffef8;color:var(--ink);font:16px/1.5 var(--sans);padding:12px 13px}.join-form textarea{min-height:118px;resize:vertical}.logo-picker{display:flex!important;align-items:center;grid-template-columns:auto 1fr;gap:14px!important;padding:14px;border:1px dashed #8e9588;background:#f2f0e5;cursor:pointer}.logo-preview{width:54px;height:54px;border:1px solid var(--line);border-radius:50%;background:#d9e1b7;display:grid;place-items:center;overflow:hidden;font:22px var(--serif);color:var(--ink)}.logo-preview img{width:100%;height:100%;object-fit:cover}.logo-picker input{position:absolute!important;width:1px!important;height:1px!important;opacity:0}.upload-hint{display:block;font-size:13px;font-weight:400;color:var(--muted)}.join-consent{display:flex!important;grid-template-columns:auto 1fr;align-items:start;font-weight:400!important;line-height:1.5}.join-consent input{margin-top:4px;accent-color:var(--accent)}.join-submit{width:100%;border:0;cursor:pointer;justify-content:space-between}.join-submit:disabled{opacity:.55;cursor:wait}.join-status{min-height:25px;margin:13px 0 0;color:var(--muted);font-size:14px}.join-status[data-kind=error]{color:#a73224}.join-status[data-kind=success]{color:#3f6932}.join-privacy{margin:16px 0 0;color:var(--muted);font-size:13px;line-height:1.55}.join-directory{padding:clamp(22px,4vw,42px);background:#fffef8}.directory-kicker{font:700 12px var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--accent)}.directory-title{margin:8px 0 4px}.directory-count{color:var(--muted);font-size:14px;margin-bottom:24px}.org-list{display:grid;gap:12px;max-height:580px;overflow:auto}.org-card{display:grid;grid-template-columns:58px 1fr;gap:16px;padding:17px 0;border-top:1px solid var(--line)}.org-logo{width:58px;height:58px;border:1px solid var(--line);background:#f1efdf;object-fit:cover;border-radius:50%}.org-card h4{font:600 20px/1.25 var(--serif);margin:0 0 5px}.org-founder{font:12px var(--mono);color:var(--muted);margin-bottom:8px}.org-card p{font-size:14px;line-height:1.55;color:#4f5b5d;margin:0}.directory-state{padding:18px 0;border-top:1px solid var(--line);font-size:15px;color:var(--muted)}.directory-links{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}.directory-links a{border-bottom:1px solid var(--ink);padding:5px 0;font-size:14px;font-weight:700}\n@media(max-width:850px){.join-shell{grid-template-columns:1fr}.join-form{border-right:0;border-bottom:1px solid var(--line)}.org-list{max-height:none}}\n@media(max-width:520px){.join-shell{box-shadow:6px 6px 0 var(--ink)}.join-form,.join-directory{padding:22px}.join-heading p{font-size:16px}.org-card{gap:12px}}\n</style></head><body><header class=\"wrap top\"><a class=\"brand\" id=\"top\" href=\"#top\"><i>✳</i>SUPERINTELLIGENCE SG <span style=\"font:11px var(--mono);color:var(--accent)\">/ .ORG</span></a><nav class=\"nav\" aria-label=\"Main navigation\"><a href=\"#learn\">Learn</a><a href=\"https://superintelligencesg.ai\">Explore</a><a class=\"button\" href=\"#participate\">Join the commons ↓</a><a class=\"button\" href=\"https://superintelligencesg.com\">The home ↗</a></nav></header><main><section class=\"wrap hero orghero\"><div><div class=\"eyebrow\">A public learning space · Singapore</div><h1>The future is too important for a <em>closed conversation.</em></h1><p class=\"lead\">A starting point for shared language, considered questions and many perspectives on the future of intelligent systems.</p><a class=\"cta\" href=\"#participate\">Join the commons ↓</a></div><aside class=\"sidequote\"><span class=\"eyebrow\">A commons is a practice</span><b>Listen. Learn.<br>Leave room to change.</b><p>Start with curiosity. Make space for different experiences. Keep the questions open.</p></aside></section><section class=\"section\" style=\"background:var(--ink);color:var(--bg)\"><div class=\"wrap sectionhead\"><div><div class=\"eyebrow\" style=\"color:#ebc953\">Questions to keep</div><h2>More than one<br>right question.</h2></div><p>These are useful starting points—not a complete checklist.</p></div><div class=\"wrap grid3\"><article class=\"item\"><span class=\"num\">01 / Who benefits?</span><h3>Who gets to shape the goal?</h3><p>Ask whose priorities are built into a system and whose needs may sit outside its design.</p></article><article class=\"item\"><span class=\"num\">02 / What changes?</span><h3>What moves when it scales?</h3><p>Consider how a small decision can travel through a workplace, service or community.</p></article><article class=\"item\"><span class=\"num\">03 / Who can respond?</span><h3>Where does judgement stay?</h3><p>Look for ways people can understand, challenge and revise consequential choices.</p></article></div></section><section class=\"section\" id=\"learn\"><div class=\"wrap sectionhead\"><div><div class=\"eyebrow\">A small field guide</div><h2>Start where you are.</h2></div><p>Open a prompt. Take one idea into a conversation. Add context from your own work and life.</p></div><div class=\"wrap guide\"><article class=\"guide-item\"><span class=\"qnum\">Guide 01</span><div><h3>What do we mean by “intelligence”?</h3><p>Separate a system’s demonstrated capability from the hopes or fears we attach to it.</p><div class=\"answer\">Try asking: What task is being performed? What evidence shows how well it works? Under what conditions might that evidence change?</div></div><button aria-expanded=\"false\" aria-label=\"Expand guide 1\">+</button></article><article class=\"guide-item\"><span class=\"qnum\">Guide 02</span><div><h3>How do we talk about uncertainty?</h3><p>Make room for what is known, what is changing and what remains open.</p><div class=\"answer\">Name the time horizon, the assumptions and the people most affected. Let confidence match the evidence.</div></div><button aria-expanded=\"false\" aria-label=\"Expand guide 2\">+</button></article><article class=\"guide-item\"><span class=\"qnum\">Guide 03</span><div><h3>What does meaningful participation look like?</h3><p>Move from inviting comment to showing how perspectives can affect a decision.</p><div class=\"answer\">Make the question specific, share the constraints, and explain how feedback will be considered and what can still change.</div></div><button aria-expanded=\"false\" aria-label=\"Expand guide 3\">+</button></article></div></section><section class=\"section\"><div class=\"wrap bandrow\"><div class=\"callout\"><div class=\"eyebrow\">Take part</div><h3>Bring a perspective.<br>Make it richer.</h3><p>Whether you work with intelligent systems or are simply curious about where they lead, the conversation benefits from more kinds of experience.</p></div><div><div class=\"eyebrow\">Keep exploring</div><p class=\"lead\">Visit the main site for the wider picture, or open an illustrative exploration in the lab.</p><a class=\"cta\" href=\"https://superintelligencesg.com\">Visit the home ↗</a></div></div></section><section class=\"section join-section\" id=\"participate\" aria-labelledby=\"join-title\"><div class=\"wrap\"><div class=\"sectionhead join-heading\"><div><div class=\"eyebrow\">Open membership · Organization directory</div><h2 id=\"join-title\">Bring your organization<br>into the commons.</h2></div><p>Joining is voluntary and immediate. Share your organization’s logo, founder and core work; your entry will appear publicly as soon as you submit it.</p></div><div class=\"join-shell\"><form class=\"join-form\" data-org-form><div class=\"join-form-top\"><span class=\"open-label\">No approval needed</span><span class=\"qnum\">01 / Join</span></div><label class=\"logo-picker\" for=\"org-logo\"><span class=\"logo-preview\" data-logo-preview aria-hidden=\"true\">✳</span><span>Upload your organization logo<span class=\"upload-hint\">PNG, JPG or WebP · up to 2 MB</span></span><input id=\"org-logo\" name=\"logo\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\" required aria-label=\"Upload organization logo\"></label><label>Organization name<input name=\"name\" required maxlength=\"100\" autocomplete=\"organization\" placeholder=\"Name shown in the public directory\"></label><label>Founder<input name=\"founder\" required maxlength=\"100\" placeholder=\"Founder or founding team\"></label><label>Core work<textarea name=\"business\" required maxlength=\"500\" placeholder=\"In a few sentences, what does your organization focus on?\"></textarea></label><label class=\"join-consent\"><input name=\"consent\" type=\"checkbox\" required><span>I represent this organization and agree that the details and logo above can be displayed publicly. The entry is published immediately without review.</span></label><label aria-hidden=\"true\" style=\"position:absolute;left:-10000px;width:1px;height:1px;overflow:hidden\">Leave this field empty<input name=\"website\" tabindex=\"-1\" autocomplete=\"off\"></label><button class=\"cta join-submit\" type=\"submit\"><span>Join and publish</span><span aria-hidden=\"true\">↗</span></button><p class=\"join-status\" data-join-status aria-live=\"polite\"></p><p class=\"join-privacy\">Only the details above are published. Please use a logo you have permission to share. To remove or correct a listing, email <a href=\"mailto:superintelligencesg@gmail.com\">superintelligencesg@gmail.com</a>.</p></form><aside class=\"join-directory\" aria-labelledby=\"directory-title\"><span class=\"directory-kicker\">The commons · Open directory</span><h3 class=\"directory-title\" id=\"directory-title\">Organizations in the conversation</h3><p class=\"directory-count\" data-directory-count>Loading the directory…</p><div class=\"org-list\" data-org-list aria-live=\"polite\"><p class=\"directory-state\">Loading public entries…</p></div><div class=\"directory-links\"><a href=\"https://superintelligencesg.com\">About the initiative ↗</a><a href=\"https://superintelligencesg.ai\">Explore the lab ↗</a></div></aside></div></div></section></main><section class=\"wrap cross\"><span>One initiative · three doors</span><div class=\"crosslinks\"><a href=\"https://superintelligencesg.com\">.com · Home</a><a href=\"https://superintelligencesg.ai\">.ai · Lab</a><a href=\"https://superintelligencesg.org\">.org · Commons</a></div></section><footer class=\"wrap\"><span>Superintelligence SG</span><span>.org</span><a href=\"mailto:superintelligencesg@gmail.com\">Email us ↗</a><a href=\"#top\">Back to top ↑</a></footer><script>document.querySelectorAll('.guide-item button').forEach(b=>b.addEventListener('click',()=>{const i=b.closest('.guide-item'),o=!i.classList.contains('open');i.classList.toggle('open',o);b.setAttribute('aria-expanded',String(o));b.textContent=o?'−':'+'}));const API='https://superintelligence-sg-org.red-fun-plan-2664.chatgpt.site',form=document.querySelector('[data-org-form]'),list=document.querySelector('[data-org-list]'),count=document.querySelector('[data-directory-count]'),status=document.querySelector('[data-join-status]'),logo=document.querySelector('#org-logo'),preview=document.querySelector('[data-logo-preview]');function say(t,k){status.textContent=t;status.dataset.kind=k||''}function render(items){list.replaceChildren();count.textContent=items.length+' '+(items.length===1?'organization':'organizations')+' · published directly';if(!items.length){const e=document.createElement('p');e.className='directory-state';e.textContent='The directory is open. Your organization can be the first to join.';list.append(e);return}for(const x of items){const c=document.createElement('article');c.className='org-card';const im=document.createElement('img');im.className='org-logo';im.src=API+'/api/media/'+encodeURIComponent(x.logo_key);im.alt=x.name+' logo';im.loading='lazy';const b=document.createElement('div'),n=document.createElement('h4'),f=document.createElement('p'),d=document.createElement('p');n.textContent=x.name;f.className='org-founder';f.textContent='Founded by '+x.founder;d.textContent=x.business;b.append(n,f,d);c.append(im,b);list.append(c)}}async function load(){try{const r=await fetch(API+'/api/organizations');if(!r.ok)throw Error();render((await r.json()).organizations||[])}catch{count.textContent='Directory temporarily unavailable';list.replaceChildren();const p=document.createElement('p');p.className='directory-state';p.textContent='Please try again in a moment. If you need help, email superintelligencesg@gmail.com.';list.append(p)}}logo.addEventListener('change',()=>{const f=logo.files&&logo.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>2097152){logo.value='';say('Choose a PNG, JPG or WebP logo no larger than 2 MB.','error');return}say('','');const im=document.createElement('img');im.alt='Selected logo preview';im.src=URL.createObjectURL(f);preview.replaceChildren(im)});form.addEventListener('submit',async e=>{e.preventDefault();say('Publishing your organization…');const b=form.querySelector('button[type=submit]');b.disabled=true;try{const r=await fetch(API+'/api/organizations',{method:'POST',body:new FormData(form)}),j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'We could not publish this entry. Please try again.');say('Your organization is now in the public directory.','success');form.reset();preview.textContent='✳';await load()}catch(err){say(err.message||'We could not publish this entry. Please try again.','error')}finally{b.disabled=false}});load();</script></body></html>\n";
const ALLOWED_ORIGINS = new Set(["https://superintelligencesg.org","https://www.superintelligencesg.org","https://superintelligence-sg-org.red-fun-plan-2664.chatgpt.site"]);
function headers(origin){const h=new Headers({"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff"});if(origin&&ALLOWED_ORIGINS.has(origin)){h.set("Access-Control-Allow-Origin",origin);h.set("Access-Control-Allow-Methods","GET, POST, OPTIONS");h.set("Access-Control-Allow-Headers","Content-Type");h.set("Vary","Origin");}return h}
function json(d,s,o){return new Response(JSON.stringify(d),{status:s,headers:headers(o)})}
function validImage(b,t){if(t==="image/png")return b.length>=8&&b[0]===137&&b[1]===80&&b[2]===78&&b[3]===71;if(t==="image/jpeg")return b.length>=3&&b[0]===255&&b[1]===216&&b[2]===255;if(t==="image/webp")return b.length>=12&&String.fromCharCode(...b.slice(0,4))==="RIFF"&&String.fromCharCode(...b.slice(8,12))==="WEBP";return false}
async function rateKey(ip){const d=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(ip||"unknown"));return Array.from(new Uint8Array(d),x=>x.toString(16).padStart(2,"0")).join("")}
export default {async fetch(request,env){const u=new URL(request.url),o=request.headers.get("Origin");if(u.pathname==="/"&&request.method==="GET")return new Response(PAGE_HTML,{headers:{"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-cache","X-Content-Type-Options":"nosniff"}});if(!u.pathname.startsWith("/api/"))return new Response("Not found",{status:404});if(request.method==="OPTIONS"){if(!o||!ALLOWED_ORIGINS.has(o))return new Response(null,{status:403});return new Response(null,{status:204,headers:headers(o)})}if(o&&!ALLOWED_ORIGINS.has(o))return json({error:"This website is not allowed to submit directory entries."},403,o);try{
if(u.pathname==="/api/organizations"&&request.method==="GET"){const r=await env.DB.prepare("SELECT id,name,founder,business,logo_key,created_at FROM organizations ORDER BY created_at DESC LIMIT 100").all();return json({organizations:r.results||[]},200,o)}
if(u.pathname.startsWith("/api/media/")&&request.method==="GET"){const key=decodeURIComponent(u.pathname.slice(11));if(!/^logos\/[0-9a-f-]{36}\.(png|jpg|webp)$/.test(key))return new Response("Not found",{status:404});const obj=await env.BUCKET.get(key);if(!obj)return new Response("Not found",{status:404});const h=new Headers();obj.writeHttpMetadata(h);h.set("Cache-Control","public, max-age=86400");h.set("X-Content-Type-Options","nosniff");h.set("Content-Security-Policy","default-src 'none'; sandbox");return new Response(obj.body,{headers:h})}
if(u.pathname==="/api/organizations"&&request.method==="POST"){if(!o||!ALLOWED_ORIGINS.has(o))return json({error:"Open the form from the Superintelligence SG Commons website."},403,o);if(Number(request.headers.get("Content-Length")||0)>2200000)return json({error:"The logo must be no larger than 2 MB."},413,o);const f=await request.formData();if(String(f.get("website")||"").trim())return json({error:"Unable to submit this entry."},400,o);if(f.get("consent")!=="on")return json({error:"Please confirm that these details can be published."},400,o);const name=String(f.get("name")||"").trim(),founder=String(f.get("founder")||"").trim(),business=String(f.get("business")||"").trim(),logo=f.get("logo");if(!name||name.length>100||!founder||founder.length>100||!business||business.length>500)return json({error:"Check the organization name, founder and core work fields."},400,o);if(!logo||typeof logo.arrayBuffer!=="function"||logo.size>2097152)return json({error:"Choose a logo no larger than 2 MB."},400,o);const type=logo.type,bytes=new Uint8Array(await logo.arrayBuffer());if(!validImage(bytes,type))return json({error:"Use a valid PNG, JPG or WebP image."},400,o);const now=Math.floor(Date.now()/1000),hash=await rateKey(request.headers.get("CF-Connecting-IP")||""),recent=await env.DB.prepare("SELECT COUNT(*) AS count FROM organization_rate_limits WHERE ip_hash=? AND created_at>?").bind(hash,now-3600).first();if(Number(recent?.count||0)>=5)return json({error:"Please wait a little before submitting another organization."},429,o);const id=crypto.randomUUID(),ext=type==="image/jpeg"?"jpg":type==="image/webp"?"webp":"png",key="logos/"+id+"."+ext;await env.BUCKET.put(key,bytes,{httpMetadata:{contentType:type}});try{await env.DB.batch([env.DB.prepare("INSERT INTO organization_rate_limits(ip_hash,created_at) VALUES(?,?)").bind(hash,now),env.DB.prepare("DELETE FROM organization_rate_limits WHERE created_at<?").bind(now-86400),env.DB.prepare("INSERT INTO organizations(id,name,founder,business,logo_key,created_at) VALUES(?,?,?,?,?,?)").bind(id,name,founder,business,key,now)])}catch(e){await env.BUCKET.delete(key);throw e}return json({ok:true,organization:{id,name,founder,business,logo_key:key,created_at:now}},201,o)}
return new Response("Not found",{status:404})}catch(e){console.error("Organization directory request failed:",e);return json({error:"The directory is temporarily unavailable. Your information has not been published."},503,o)}}};
